Database.Cursor emptyCursor = new Database.Cursor();
System.assertNotEquals(null, emptyCursor);
Database.Cursor.DeleteFilter filter = Database.Cursor.DeleteFilter.NO_FILTER;
System.assertEquals(Database.Cursor.DeleteFilter.NO_FILTER, filter);
insert new Account(Name = 'Cursor Sync One');
insert new Account(Name = 'Cursor Sync Two');
Database.PaginationCursor page = Database.getPaginationCursor('SELECT Id, Name FROM Account ORDER BY Name');
Database.CursorFetchResult pageResult = page.fetchPage(0, 2);
System.assertEquals(2, pageResult.getRecords().size());
System.assertEquals(0, pageResult.getNextIndex());
System.assertEquals(0, pageResult.getNumDeletedRecords());
System.assert(pageResult.isDone());
System.assertEquals(0, page.fetchDeleted(0, 1));
Datetime start = Datetime.now().addDays(-1);
Datetime finish = start.addHours(1);
Database.GetDeletedResult deleted = Database.getDeleted('Account', start, finish);
System.assertEquals(0, deleted.getDeletedRecords().size());
System.assertEquals(null, deleted.getEarliestDateAvailable());
System.assertNotEquals(null, deleted.getLatestDateCovered());
